import { CloudLogo, CloudLogoHome } from '@ds/icons/logos';
import { PromoTag } from '@ds/promo-tag';
import { TooltipProps } from '@ds/tooltip';
import { extractDataTestProps, WithSupportProps } from '@ds/utils';
import cn from 'classnames';
import { MouseEventHandler, useEffect, useMemo, useState } from 'react';

import { HeaderButton } from '../HeaderButton';
import { HEADER_LOGO_MODE, HeaderLogoMode, MAP_LOGO_MODE_TO_APPEARANCE, MAP_LOGO_MODE_TO_LABEL } from './constants';
import styles from './styles.module.scss';

export type LogoProps = WithSupportProps<{
  /** Флаг загрузки — логотип показывается в состоянии загрузки кнопки. */
  loading?: boolean;
  /** Путь до кастомного изображения логотипа. Без пропа (или при ошибке загрузки) — дефолтная иконка. */
  path?: string;
  /** Режим окружения — отображается промо-тегом рядом с дефолтной иконкой (не для `'prod'`). */
  mode?: HeaderLogoMode;
  /** Ссылка логотипа. */
  href: string;
  /** Колбэк клика по логотипу. */
  onClick?: MouseEventHandler<HTMLAnchorElement>;
  /** CSS-класс корневого элемента. */
  className?: string;
  /** Настройки тултипа логотипа. */
  tooltip?: TooltipProps;
}>;

export function Logo({ path, loading, mode, href, onClick, className, tooltip, ...rest }: LogoProps) {
  const [error, setError] = useState<boolean>(false);

  useEffect(() => {
    setError(false);
  }, [path, loading]);

  const logo = useMemo(() => {
    if (path && !error) {
      return (
        <img
          src={path}
          alt='logo'
          className={styles.logoImg}
          onLoad={() => {
            setError(false);
          }}
          onError={() => {
            setError(true);
          }}
        />
      );
    }

    const showMode = mode && mode !== HEADER_LOGO_MODE.Prod;

    return (
      <span className={styles.logoWrap} data-with-mode={showMode || undefined}>
        <span className={styles.iconStack}>
          <CloudLogo size={24} className={cn(styles.icon, styles.iconDefault)} />
          <CloudLogoHome size={24} className={cn(styles.icon, styles.iconHover)} />
        </span>

        {showMode && (
          <PromoTag label={MAP_LOGO_MODE_TO_LABEL[mode]} size='xs' appearance={MAP_LOGO_MODE_TO_APPEARANCE[mode]} />
        )}
      </span>
    );
  }, [error, mode, path]);

  return (
    <HeaderButton
      as='a'
      tooltip={tooltip}
      className={cn(styles.logo, className)}
      href={href}
      tabIndex={0}
      onClick={onClick}
      loading={loading}
      icon={logo}
      {...extractDataTestProps(rest)}
    />
  );
}
