import { Divider } from '@ds/divider';
import { ChevronLeftSVG } from '@ds/icons/interface/system';
import cn from 'classnames';
import { ReactNode } from 'react';

import { headerLocale } from '../../../../locale';
import { HeaderButton } from '../../../HeaderButton';
import styles from './styles.module.scss';

export type MenuHeaderBrandProps = {
  /** Логотип в шапке меню. */
  logo?: ReactNode;
  /** Колбэк клика по кнопке закрытия меню. */
  onClose(): void;
  /** CSS-класс корневого элемента. */
  className?: string;
  isMobile?: boolean;
};

export function MenuHeaderBrand({ logo, onClose, className, isMobile }: MenuHeaderBrandProps) {
  const { t } = headerLocale.useTranslations();

  return (
    <div className={cn(styles.container, className)} data-mobile={isMobile || undefined}>
      {logo}
      <Divider orientation='vertical' />

      <HeaderButton className={styles.closeButton} onClick={onClose} icon={<ChevronLeftSVG />} label={t('close')} />
    </div>
  );
}
